operation.add:
} elseif ($data['route'] == 'extension/notes/note' && $key == 'note_id') {
	$query = $this->db->query("SELECT * FROM " . DB_PREFIX . "seo_url WHERE `query` = 'note_id=" . (int)$value . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "'");

	if ($query->num_rows && $query->row['keyword']) {
		$url .= '/' . $query->row['keyword'];

		unset($data[$key]);
	}
} elseif ($key == 'topic_path') {
	$topics = '';

	foreach (explode('_', $value) as $topic) {
		$query = $this->db->query("SELECT * FROM " . DB_PREFIX . "seo_url WHERE `query` = 'note_topic_id=" . (int)$topic . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "'");

		if ($query->num_rows && $query->row['keyword']) {
			$topics .= '/' . $query->row['keyword'];
		} else {
			$topics = '';

			break;
		}
	}

	if ($topics) {
		$url .= $topics;

		unset($data[$key]);
	}
} elseif ($data['route'] == 'extension/notes/offer' && $key == 'offer_id') {
	$list = $this->db->query("SELECT * FROM " . DB_PREFIX . "seo_url WHERE `query` = 'extension/notes/offers' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "'");
	$query = $this->db->query("SELECT * FROM " . DB_PREFIX . "seo_url WHERE `query` = 'offer_id=" . (int)$value . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "'");

	if ($list->num_rows && $list->row['keyword'] && $query->num_rows && $query->row['keyword']) {
		$url .= '/' . $list->row['keyword'] . '/' . $query->row['keyword'];

		unset($data[$key]);
	}
